def compute(vars):
    occupied_space = vars["v1"]
    total_facility_space = vars["v2"]

    if total_facility_space == 0:
        return None

    portion = occupied_space / total_facility_space

    return {
        "value": round(portion, 3),
        "trace": {
            "occupied_space": occupied_space,
            "total_facility_space": total_facility_space,
            "portion": portion,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
